// 정점 셰이더: 점마다 한 번, 위치 결정
attribute vec3 aPos; attribute vec2 aUV;
varying vec2 vUV;            // → 프래그먼트로 넘김(보간됨)
uniform mat4 uMVP;
void main() { vUV = aUV; gl_Position = uMVP * vec4(aPos, 1.0); }

// 프래그먼트 셰이더: 픽셀마다 한 번, 색 결정
varying vec2 vUV;           // 보간된 값 도착
void main() { gl_FragColor = texture2D(uTex, vUV); }

attribute vec3 aPos;   // 정점마다 다름 (위치·UV·법선)
attribute vec2 aUV;
uniform mat4 uMVP;     // 그리는 동안 고정 (행렬·시간·색)
uniform float uTime;
varying vec2 vUV;      // 정점 → 프래그먼트 (보간)

void main() {
  vUV = aUV;                        // varying 에 담아 넘김
  gl_Position = uMVP * vec4(aPos, 1.0);
}
// 현대 GLSL: attribute→in, varying→out/in (개념 동일)

// 나쁨: 픽셀마다 갈리는 분기 (발산)
if (d < 0.5) color = a; else color = b;

// 좋음: 분기 없는 수식
color = mix(a, b, step(0.5, d));         // 또는 smoothstep

// 디버깅: 값을 색으로 (로그가 없다)
